"use strict";

function catalogEvidence(state, evidenceId) {
  if (!evidenceId) return state;
  if ((state.evidence || []).includes(evidenceId)) return state;
  return Object.assign({}, state, { evidence: (state.evidence || []).concat(evidenceId) });
}

function getDiscovered(state, game) {
  const have = new Set(state.evidence || []);
  return (game.evidence || []).filter((item) => have.has(item.id));
}

module.exports = { catalogEvidence, getDiscovered };
